<template>
  <div class="swiper-container">
    <swiper :direction="direction" :slidesPerView="1" :centeredSlides="true" :loop="true" :speed="speed"
      :effect="'fade'" :autoplay="{
        delay: delay,
        disableOnInteraction: false,
      }" :modules="[Autoplay, Virtual]" :virtual="true" @swiper="onSwiper" @slideChange="onSlideChange"
      class="mySwiper">
      <swiper-slide v-for="(slide, index) in slides" :key="index" :virtualIndex="index">
        <div class="slide-content">
          <div class="box">
            <div class="avatar">
              <img :src="slide.icon" alt="">
            </div>
            <div class="name">
              {{ prousername(slide.user) }}
              <span>***</span>
            </div>
            <div class="say" v-if="slideModel == 'type1'">{{ slide.text }}</div>
            <div class="good-1" v-if="slideModel == 'type2'">下单<span>1</span>号商品</div>
            <div class="good-2" v-if="slideModel == 'type3'">抢购<span>1</span>号{{ title }}</div>
          </div>
        </div>
      </swiper-slide>
    </swiper>
    <div class="setting">
      <a-space>
        <span @click="refreshPage">刷新</span>
        <span @click="createWindow">设置</span>
      </a-space>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, onUnmounted, nextTick } from 'vue';
import { Swiper, SwiperSlide } from 'swiper/vue';
import { Autoplay, Virtual } from 'swiper/modules';
import { useWindow } from '@/utils/useWindow';
const { createNewWindow } = useWindow();
import { Store } from '@tauri-apps/plugin-store';
import { appCacheDir, appConfigDir, join } from '@tauri-apps/api/path'
import { getRandomItem, getRandomInt } from '@/utils/index.js'
import users from '@/utils/users.js'
import 'swiper/css';
import 'swiper/css/pagination';
import 'swiper/css/navigation';
import { window } from '@tauri-apps/api';
const prousername = (user) => {
  return Array.from(user)[0]
}
const swiperInstance = ref(null);
const slides = ref([]);
const direction = ref('vertical')
let slide = []
const slideModel = ref()
const title = ref()
const speed = ref(500)
const delay = ref(2000)
//   user.value = getRandomItem(users)
let nextId = 0; // 用于生成不重复的 slide ID

onMounted(async () => {
  const configDir = await appConfigDir();
  console.log(configDir)
  const storePath = await join(configDir, 'settings');
  const store = await Store.load(storePath);
  
  // 获取配置，如果为undefined则使用默认值
  const savedPath = await store.get('config');
  
  // 定义更严谨的默认配置
  const defaultConfig = {
    content: '默认文本1\n默认文本2', // 确保是字符串类型，使用换行分隔
    direction: 'vertical',
    type: 'type2',
    title: '默认标题',
    speed: 0.5,
    delay: 2,
  };
  
  // 合并配置，确保所有必要字段存在且类型正确
  const config = {
    ...defaultConfig,
    ...(savedPath || {}) // 只合并有效对象
  };
  
  // 关键修复：确保content是字符串类型
  let content = typeof config.content === 'string' 
    ? config.content 
    : defaultConfig.content; // 如果不是字符串，使用默认值
  console.log(config)
  // 处理内容
  content = content.split('\n')
    .map(line => line.trim())
    .filter(line => line.length > 0);
  
  // 后续代码保持不变
  slide = content;
  direction.value = config.direction || defaultConfig.direction;
  slideModel.value = config.type || defaultConfig.type;
  title.value = config.title || defaultConfig.title;  
  speed.value = (typeof config.speed === 'number' ? config.speed : defaultConfig.speed) * 1000;
  delay.value = (typeof config.delay === 'number' ? config.delay : defaultConfig.delay) * 1000;
  console.log(`speed:${speed.value}`)
  // 保存默认配置（如果需要）
  if (!savedPath) {
    await store.set('config', defaultConfig);
    await store.save();
  }
  
  // 生成幻灯片
  content.map((item) => {
    const imageUrl = new URL(
      `../assets/grade_images/level_${getRandomInt(1, 45)}.png`,
      import.meta.url
    ).href;
    slides.value.push({ icon: imageUrl, user: getRandomItem(users), text: item })
  })

  nextTick(() => {
    swiperInstance.ref?.autoplay?.start();
  })
})



// 动态生成新元素
const generateNewSlide = () => {
  const imageUrl = new URL(
    `../assets/grade_images/level_${getRandomInt(1, 45)}.png`,
    import.meta.url
  ).href;
  const newSlide = { icon: imageUrl, user: getRandomItem(users), text: getRandomItem(slide) }
  slides.value.push(newSlide);
  // 如果需要，可以在这里移除旧的元素以控制元素数量
  // 例如：if (slides.value.length > 50) slides.value.shift();
};

const onSwiper = (swiper) => {
  console.log('onSwiper')
  swiperInstance.ref = swiper;
  // 确保刷新后自动播放    
  // swiper.autoplay.start();
};

const onSlideChange = (swiper) => {
  // 当接近列表末尾时，动态生成新元素
  // 这里可以根据实际情况调整触发生成新元素的阈值
  const threshold = 3; // 距离结束还有3个元素时触发
  if (swiper.isEnd && swiper.slides.length - swiper.activeIndex <= threshold) {
    console.log('接近末尾，生成新元素...');
    generateNewSlide();
    // Swiper 在虚拟模式下会自动更新 DOM，但有时需要手动触发更新
    // 尤其是在数据量变化时，`update()` 方法可以帮助 Swiper 重新计算布局
    swiper.update();
  }
};

onUnmounted(() => {
  if (swiperInstance.ref) {
    swiperInstance.ref.destroy();
  }
});

const createWindow = () => {
  createNewWindow('#/setting', '设置', 'setting', { height: 600 })
}

const refreshPage = () => {
  location.reload();
}
</script>

